  `cv_document_id` BINARY(16),
  `blind_score` DECIMAL(6,2),
  `scores` JSON COMMENT 'Per criterion and panel member',
  `stage` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `staff_id` BINARY(16) COMMENT 'Set on appointment (after identity matching)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_job_application_vacancy_id` (`tenant_id`, `vacancy_id`),
  CONSTRAINT `ck_job_application__stage` CHECK (`stage` IN ('applied', 'shortlisted', 'interview', 'references', 'checks', 'offer', 'appointed', 'rejected', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/restricted] Application for a vacancy (blind scoring by default; references and checks before offer)';

CREATE TABLE `payroll_run` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `employer_scope_id` BINARY(16) NOT NULL,
  `period_label` VARCHAR(7) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'YYYY-MM',
  `pay_date` DATE NOT NULL,
  `gross_total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `net_total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `prepared_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16),
  `second_approver_id` BINARY(16),
  `bank_file_document_id` BINARY(16),
  `journal_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_run_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_payroll_run_employer_scope_id_period_label` (`tenant_id`, `employer_scope_id`, `period_label`),
  KEY `ix_payroll_run_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_payroll_run_journal_id` (`tenant_id`, `journal_id`),
  CONSTRAINT `ck_payroll_run__status` CHECK (`status` IN ('draft', 'calculated', 'exceptions_review', 'approved', 'exported', 'posted', 'cancelled')),
  CONSTRAINT `ck_payroll_run__two_person` CHECK (second_approver_id IS NULL OR approved_by IS NULL OR second_approver_id <> approved_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/restricted] Pay run (two-person approval, bank file export, ledger posting)';

CREATE TABLE `payroll_tax_table` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `table_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `bands` JSON NOT NULL,
  `effective_from` DATE NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_tax_table_table_kind_version` (`tenant_id`, `table_kind`, `version`),
  CONSTRAINT `ck_payroll_tax_table__table_kind` CHECK (`table_kind` IN ('paye', 'pension', 'nhf', 'nhis', 'other')),
  CONSTRAINT `ck_payroll_tax_table__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/config/internal] Versioned payroll statutory table (PAYE, pension/PenCom, NHF)';

CREATE TABLE `payslip` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `payroll_run_id` BINARY(16) NOT NULL,
  `staff_post_id` BINARY(16) NOT NULL,
  `gross_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `deductions_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `net_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `line_items` JSON NOT NULL COMMENT 'Earnings and deductions by code with tax table versions used',
  `bank_account_enc` VARBINARY(1024) COMMENT 'Envelope-encrypted bank_account. Payee bank account',
  `bank_account_last4` CHAR(4) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Last four characters of bank_account for masked display',
  `exception_flags` JSON COMMENT 'Exceptions reviewed before approval',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payslip_payroll_run_id_staff_post_id` (`tenant_id`, `payroll_run_id`, `staff_post_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/restricted] Payslip of one staff post in a pay run';

CREATE TABLE `staff_absence` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_id` BINARY(16) NOT NULL,
  `staff_post_id` BINARY(16),
  `absence_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `ends_at` DATETIME(6) NOT NULL,
  `is_planned` BOOLEAN NOT NULL DEFAULT FALSE,
  `reason_note` MEDIUMBLOB COMMENT 'Medical or personal detail (encrypted)',
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_absence_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_staff_absence_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_staff_absence__status` CHECK (`status` IN ('requested', 'approved', 'rejected', 'recorded', 'cancelled')),
  CONSTRAINT `ck_staff_absence__window` CHECK (ends_at > starts_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/confidential] Staff absence (triggers the cover process and G8 checks)';

CREATE TABLE `staff_pulse_response` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `survey_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `org_unit_id` BINARY(16),
  `answers` JSON NOT NULL,
  `submitted_on` DATE NOT NULL COMMENT 'Date only — no timestamp to resist re-identification',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_staff_pulse_response_scope` (`tenant_id`, `scope_node_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/event/internal] Anonymous staff wellbeing pulse response (reported only in aggregate; no staff identifier stored)';

CREATE TABLE `training_completion` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `course_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `assigned_on` DATE NOT NULL,
  `completed_on` DATE,
  `score` DECIMAL(6,3),
  `passed` BOOLEAN,
  `certificate_document_id` BINARY(16),
  `expires_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_training_completion_staff_id_course_id` (`tenant_id`, `staff_id`, `course_id`),
  KEY `ix_training_completion_course_id` (`tenant_id`, `course_id`),
  CONSTRAINT `ck_training_completion__status` CHECK (`status` IN ('assigned', 'in_progress', 'passed', 'failed', 'expired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/confidential] Completion of a training course by an adult (writes to Staff 360, CPD and the Education Passport)';

CREATE TABLE `training_course` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `topic` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'child protection, safe schools, first aid, fire safety, data protection, online safety, SEND awareness',
  `course_space_id` BINARY(16),
  `package_format` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `pass_mark` DECIMAL(6,3),
  `renewal_months` SMALLINT,
  `required_for_roles` JSON COMMENT 'Role codes',
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_training_course_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_training_course_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  KEY `ix_training_course_course_space_id` (`tenant_id`, `course_space_id`),
  CONSTRAINT `ck_training_course__package_format` CHECK (`package_format` IS NULL OR `package_format` IN ('native_lms', 'scorm', 'xapi')),
  CONSTRAINT `ck_training_course__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/config/internal] Safeguarding or statutory training course (native LMS staff course space or SCORM/xAPI package)';

CREATE TABLE `vacancy` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `org_unit_id` BINARY(16),
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `subjects` JSON COMMENT 'Subjects and levels needed (links to coverage gaps)',
  `coverage_gap_id` BINARY(16) COMMENT 'Gap that justified the vacancy',
  `closing_on` DATE,
  `workflow_instance_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_vacancy_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_vacancy_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_vacancy_coverage_gap_id` (`tenant_id`, `coverage_gap_id`),
  KEY `ix_vacancy_workflow_instance_id` (`tenant_id`, `workflow_instance_id`),
  CONSTRAINT `ck_vacancy__status` CHECK (`status` IN ('draft', 'open', 'closed', 'filled', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/transaction/internal] Vacancy in the recruitment workflow';

-- ============================================================================
-- Domain ACA — Academic structure — calendars, subjects, programmes, qualifications, classes, departments and courses
-- ============================================================================

CREATE TABLE `class_group` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `campus_id` BINARY(16),
  `period_id` BINARY(16) NOT NULL COMMENT 'Session',
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `education_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Primary 4B, JSS 1 Gold, SS 2 Science A',
  `stream` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `programme_id` BINARY(16),
  `parent_class_id` BINARY(16) COMMENT 'Sets and cross-class groupings link to parent classes',
  `form_teacher_staff_id` BINARY(16),
  `room_id` BINARY(16),
  `capacity` SMALLINT NOT NULL COMMENT 'Room capacity and state policy (default 40 primary, 45 secondary)',
  `language_of_instruction` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin,
  `session_shift` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Double-shift schools',
  `rolled_from_id` BINARY(16) COMMENT 'Academic Year Rollover Wizard',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_class_group_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_class_group_institution_id_period_id_name` (`tenant_id`, `institution_id`, `period_id`, `name`),
  KEY `ix_class_group_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_class_group_parent_class_id` (`tenant_id`, `parent_class_id`),
  KEY `ix_class_group_room_id` (`tenant_id`, `room_id`),
  KEY `ix_class_group_rolled_from_id` (`tenant_id`, `rolled_from_id`),
  CONSTRAINT `ck_class_group__kind` CHECK (`kind` IN ('arm', 'set', 'cohort', 'course_section', 'group')),
  CONSTRAINT `ck_class_group__session_shift` CHECK (`session_shift` IS NULL OR `session_shift` IN ('morning', 'afternoon', 'evening', 'single')),
  CONSTRAINT `ck_class_group__status` CHECK (`status` IN ('draft', 'active', 'closed', 'archived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/internal] Class 360 — class (arm), set, cohort or course section for a period';

CREATE TABLE `class_membership` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `class_group_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `is_arm` BOOLEAN NOT NULL COMMENT 'True for the learner''s single class arm',
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_class_membership_class_group_id_learner_id_valid_from` (`tenant_id`, `class_group_id`, `learner_id`, `valid_from`),
  KEY `ix_class_membership_learner_id` (`tenant_id`, `learner_id`),
  CONSTRAINT `ck_class_membership__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/link/confidential] Learner membership of a class, set or grouping (exactly one class arm per session; sets in addition)';

CREATE TABLE `class_subject_plan` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `class_group_id` BINARY(16) NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `is_mandatory` BOOLEAN NOT NULL COMMENT 'Pre-filled mandatory subjects cannot be removed',
  `periods_per_week` SMALLINT NOT NULL,
  `required_hours` DECIMAL(6,1) COMMENT 'From the adopted curriculum',
  `room_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `curriculum_version_id` BINARY(16) COMMENT 'Resolved and stored for history',
  `language_of_instruction` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin,
  `copied_from_id` BINARY(16),
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_class_subject_plan_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_class_subject_plan_class_group_id_subject_id_valid_from` (`tenant_id`, `class_group_id`, `subject_id`, `valid_from`),
  KEY `ix_class_subject_plan_copied_from_id` (`tenant_id`, `copied_from_id`),
  CONSTRAINT `ck_class_subject_plan__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/config/internal] Subject offered to a class — periods per week, room type, curriculum version, language of instruction';

CREATE TABLE `course_registration` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `course_section_id` BINARY(16) NOT NULL,
  `is_carry_over` BOOLEAN NOT NULL DEFAULT FALSE,
  `units` DECIMAL(4,1) NOT NULL,
  `adviser_staff_id` BINARY(16),
  `approved_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_course_registration_learner_id_course_section_id` (`tenant_id`, `learner_id`, `course_section_id`),
  KEY `ix_course_registration_course_section_id` (`tenant_id`, `course_section_id`),
  CONSTRAINT `ck_course_registration__status` CHECK (`status` IN ('draft', 'submitted', 'adviser_approved', 'registered', 'dropped'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/transaction/confidential] Student semester course registration (unit limits, prerequisites, carry-overs, clashes, adviser approval)';

CREATE TABLE `course_section` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `course_id` BINARY(16) NOT NULL,
  `period_id` BINARY(16) NOT NULL COMMENT 'Semester',
  `section_code` VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `capacity` SMALLINT,
  `consuming_department_ids` JSON COMMENT 'Service courses visible to consuming departments',
  `assessment_scheme` JSON COMMENT 'CA and exam components',
  `external_examiner` JSON COMMENT 'External examiners and moderators (FR-ACA-114)',
  `allocation_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'HOD approval publishes to timetables and the LMS',
  `approved_by` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_course_section_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_course_section_course_id_period_id_section_code` (`tenant_id`, `course_id`, `period_id`, `section_code`),
  KEY `ix_course_section_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_course_section__allocation_status` CHECK (`allocation_status` IN ('draft', 'proposed', 'approved', 'published', 'applied', 'allocated', 'waitlisted', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/internal] Course offering section per semester (lecturer of record, co-lecturers, TAs, LMS space, assessment components)';

CREATE TABLE `teaching_assignment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `class_subject_plan_id` BINARY(16) COMMENT 'School',
  `course_section_id` BINARY(16) COMMENT 'Tertiary',
  `staff_id` BINARY(16) NOT NULL,
  `staff_post_id` BINARY(16) NOT NULL,
  `role` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `authorisation_id` BINARY(16) COMMENT 'Authorisation that satisfied G3',
  `exception_id` BINARY(16) COMMENT 'Time-boxed exception when unauthorised',
  `justification` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci COMMENT 'Out-of-specialism or overload reason (HOD)',
  `weekly_periods` DECIMAL(5,2),
  `of_record_key` BINARY(16) GENERATED ALWAYS AS (IF(`role` = 'teacher_of_record' AND `valid_to` IS NULL, COALESCE(`class_subject_plan_id`, `course_section_id`), NULL)) STORED,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_teaching_assignment_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_teaching_assignment_of_record_key` (`tenant_id`, `of_record_key`),
  KEY `ix_teaching_assignment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_teaching_assignment_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_teaching_assignment_class_subject_plan_id` (`tenant_id`, `class_subject_plan_id`),
  KEY `ix_teaching_assignment_course_section_id` (`tenant_id`, `course_section_id`),
  CONSTRAINT `ck_teaching_assignment__role` CHECK (`role` IN ('teacher_of_record', 'co_teacher', 'teaching_assistant', 'specialist')),
  CONSTRAINT `ck_teaching_assignment__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT `ck_teaching_assignment__target` CHECK ((class_subject_plan_id IS NULL) <> (course_section_id IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/link/internal] Teacher of record or co-teacher for a class-subject or lecturer for a course section (effective-dated)';

-- ============================================================================
-- Domain CUR — Curriculum 360, adoption, teaching chain evidence and zero-gap coverage assurance
-- ============================================================================

CREATE TABLE `coverage_gap` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `rule` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `class_subject_plan_id` BINARY(16),
  `course_section_id` BINARY(16),
  `teaching_assignment_id` BINARY(16),
  `learners_affected` SMALLINT NOT NULL,
  `owner_role` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_user_id` BINARY(16),
  `due_on` DATE NOT NULL,
  `escalation_level` SMALLINT NOT NULL DEFAULT 0,
  `escalated_to_scope_id` BINARY(16),
  `suggested_fixes` JSON COMMENT 'Ranked qualified teachers with spare load, LGA deployment, remote teaching',
  `accepted_by_head` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Gap accepted (e.g. leaver handover)',
  `opened_at` DATETIME(6) NOT NULL,
  `closed_at` DATETIME(6),
  `closed_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `open_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(`status` IN ('open','in_progress','escalated'), CONCAT(`rule`, ':', HEX(COALESCE(`class_subject_plan_id`, `course_section_id`, `teaching_assignment_id`, `institution_id`))), NULL)) STORED COMMENT 'rule:target while open; NULL when closed (one open gap per target per rule)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_coverage_gap_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_coverage_gap_open_key` (`tenant_id`, `open_key`),
  KEY `ix_coverage_gap_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_coverage_gap_institution_id_status` (`tenant_id`, `institution_id`, `status`),
  KEY `ix_coverage_gap_due_on` (`tenant_id`, `due_on`),
  KEY `ix_coverage_gap_class_subject_plan_id` (`tenant_id`, `class_subject_plan_id`),
  KEY `ix_coverage_gap_course_section_id` (`tenant_id`, `course_section_id`),
  KEY `ix_coverage_gap_teaching_assignment_id` (`tenant_id`, `teaching_assignment_id`),
  CONSTRAINT `ck_coverage_gap__rule` CHECK (`rule` IN ('g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'g7', 'g8', 'g9', 'g10', 'g11', 'g12')),
  CONSTRAINT `ck_coverage_gap__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_coverage_gap__status` CHECK (`status` IN ('open', 'in_progress', 'escalated', 'accepted', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/transaction/internal] Coverage gap — a breached teaching-chain invariant (G1–G12) with owner, severity, due date and escalation';

CREATE TABLE `delivery_log` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `lesson_occurrence_id` BINARY(16) NOT NULL,
  `teaching_assignment_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `node_ids` JSON NOT NULL COMMENT 'Objectives covered',
  `delivered_minutes` INT NOT NULL,
  `is_as_planned` BOOLEAN NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'class_page, staff_app, lms_lesson',
  `learners_present` SMALLINT,
  `note` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `delivered_on` DATE NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_delivery_log_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_delivery_log_lesson_occurrence_id` (`tenant_id`, `lesson_occurrence_id`),
  KEY `ix_delivery_log_teaching_assignment_id` (`tenant_id`, `teaching_assignment_id`),
  CONSTRAINT `ck_delivery_log__source` CHECK (`source` IN ('class_page', 'staff_app', 'lms_lesson', 'import'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/event/internal] Evidence that a lesson was delivered — objectives covered, learners present, note (G6)';

CREATE TABLE `gap_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `gap_id` BINARY(16) NOT NULL,
  `event_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor` BINARY(16) COMMENT 'User or agent service identity',
  `detail` JSON,
  `linked_thread_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Workspace-messaging thread (FR-COM-110)',
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_gap_event_gap_id` (`tenant_id`, `gap_id`),
  CONSTRAINT `ck_gap_event__event_kind` CHECK (`event_kind` IN ('opened', 'updated', 'reminded', 'fix_proposed', 'escalated', 'accepted', 'closed', 'reopened'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/event/internal] History of a coverage gap (opened, reminded, escalated, fix proposed, closed) — append-only';

CREATE TABLE `scheme_of_work` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `class_subject_plan_id` BINARY(16),
  `course_section_id` BINARY(16),
  `teaching_assignment_id` BINARY(16) NOT NULL,
  `curriculum_version_id` BINARY(16) NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `is_auto_drafted` BOOLEAN NOT NULL DEFAULT TRUE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scheme_of_work_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_scheme_of_work_class_subject_plan_id` (`tenant_id`, `class_subject_plan_id`),
  KEY `ix_scheme_of_work_course_section_id` (`tenant_id`, `course_section_id`),
  KEY `ix_scheme_of_work_teaching_assignment_id` (`tenant_id`, `teaching_assignment_id`),
  CONSTRAINT `ck_scheme_of_work__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/transaction/internal] Scheme of work for a teaching assignment — auto-drafted from curriculum hours and the calendar, edited by the teacher (G5, G10)';

CREATE TABLE `scheme_week` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scheme_id` BINARY(16) NOT NULL,
  `week_no` SMALLINT NOT NULL,
  `week_starts_on` DATE NOT NULL,
  `node_ids` JSON NOT NULL COMMENT 'Curriculum objectives planned for the week',
  `planned_minutes` INT,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scheme_week_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_scheme_week_scheme_id_week_no` (`tenant_id`, `scheme_id`, `week_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/link/internal] Week of a scheme of work with the curriculum objectives placed in it';

-- ============================================================================
-- Domain TIM — Timetable, lesson occurrences, cover rota, duties and room bookings
-- ============================================================================

CREATE TABLE `duty_rota` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `duty_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `location` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci,
  `cycle_day` SMALLINT NOT NULL,
  `period_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `backup_staff_id` BINARY(16),
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_duty_rota_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_duty_rota__duty_kind` CHECK (`duty_kind` IN ('break_duty', 'lunch_duty', 'gate_duty', 'on_call', 'bus_duty')),
  CONSTRAINT `ck_duty_rota__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/config/internal] Break, duty or on-call rota slot (fair distribution; on-call responders for BEH-105)';

CREATE TABLE `lesson_occurrence` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `timetable_lesson_id` BINARY(16) NOT NULL,
  `occurs_on` DATE NOT NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `ends_at` DATETIME(6) NOT NULL,
  `staff_id` BINARY(16) NOT NULL COMMENT 'Teacher actually responsible (cover changes it)',
  `room_id` BINARY(16),
  `is_remote` BOOLEAN NOT NULL DEFAULT FALSE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lesson_occurrence_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_lesson_occurrence_timetable_lesson_id_occurs_on` (`tenant_id`, `timetable_lesson_id`, `occurs_on`),
  KEY `ix_lesson_occurrence_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_lesson_occurrence_staff_id_occurs_on` (`tenant_id`, `staff_id`, `occurs_on`),
  KEY `ix_lesson_occurrence_room_id` (`tenant_id`, `room_id`),
  CONSTRAINT `ck_lesson_occurrence__status` CHECK (`status` IN ('scheduled', 'taught', 'covered', 'cancelled', 'remote'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/transaction/internal] Dated occurrence of a lesson, materialised when a register, cover, delivery log or rating refers to it';

CREATE TABLE `letting` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `room_booking_id` BINARY(16) NOT NULL,
  `hirer_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `hirer_contact` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `charge_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `invoice_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_letting_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_letting_room_booking_id` (`tenant_id`, `room_booking_id`),
  KEY `ix_letting_invoice_id` (`tenant_id`, `invoice_id`),
  CONSTRAINT `ck_letting__status` CHECK (`status` IN ('requested', 'confirmed', 'declined', 'cancelled', 'completed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/transaction/internal] External letting of facilities with charges posted to finance';

CREATE TABLE `period_structure` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `timetable_id` BINARY(16) NOT NULL,
  `structure_code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Year-group structure',
  `cycle_day` SMALLINT NOT NULL,
  `period_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `starts_at` TIME NOT NULL,
  `ends_at` TIME NOT NULL,
  `is_teaching` BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Breaks and registration periods are not teaching',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_period_structure_timetable_id_structure_code_cycle_d_efbde080` (`tenant_id`, `timetable_id`, `structure_code`, `cycle_day`, `period_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/config/internal] Bell schedule — named periods with times per day of the cycle and per year-group structure';

CREATE TABLE `room_booking` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `room_id` BINARY(16),
  `asset_id` BINARY(16) COMMENT 'Shared resource',
  `booked_by` BINARY(16) NOT NULL,
  `purpose` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `ends_at` DATETIME(6) NOT NULL,
  `recurrence` JSON COMMENT 'RRULE for recurring bookings',
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_room_booking_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_room_booking_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_room_booking_room_id_starts_at` (`tenant_id`, `room_id`, `starts_at`),
  KEY `ix_room_booking_asset_id` (`tenant_id`, `asset_id`),
  CONSTRAINT `ck_room_booking__status` CHECK (`status` IN ('requested', 'confirmed', 'declined', 'cancelled', 'completed')),
  CONSTRAINT `ck_room_booking__window` CHECK (ends_at > starts_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/transaction/internal] Booking of a room or shared resource (labs, halls, laptop trolleys) — recurring, approval rules, weekly limits';

CREATE TABLE `timetable` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `period_id` BINARY(16) NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `cycle_weeks` SMALLINT NOT NULL DEFAULT 1,
  `sessions_per_day` SMALLINT NOT NULL DEFAULT 1 COMMENT 'Double-shift schools',
  `solver_run` JSON COMMENT 'Constraint set, objective value and unmet soft constraints',
  `unmet_requirements` JSON COMMENT 'Mandatory hours not met (publication blocked unless an exception exists)',
  `exception_id` BINARY(16),
  `published_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_timetable_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_timetable_institution_id_period_id_version` (`tenant_id`, `institution_id`, `period_id`, `version`),
  KEY `ix_timetable_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_timetable__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/config/internal] Timetable version for an institution and session (one- or two-week cycles, structures per year group)';

CREATE TABLE `timetable_lesson` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `timetable_id` BINARY(16) NOT NULL,
  `class_group_id` BINARY(16) NOT NULL,
  `class_subject_plan_id` BINARY(16),
  `course_section_id` BINARY(16),
  `subject_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `room_id` BINARY(16),
  `cycle_day` SMALLINT NOT NULL,
  `period_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `duration_minutes` INT NOT NULL,
  `lesson_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'lesson' COMMENT 'lesson, lecture, tutorial, practical, live_class',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_timetable_lesson_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_timetable_lesson_timetable_id_cycle_day_period_code` (`tenant_id`, `timetable_id`, `cycle_day`, `period_code`),
  KEY `ix_timetable_lesson_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_timetable_lesson_class_group_id` (`tenant_id`, `class_group_id`),
  KEY `ix_timetable_lesson_class_subject_plan_id` (`tenant_id`, `class_subject_plan_id`),
  KEY `ix_timetable_lesson_course_section_id` (`tenant_id`, `course_section_id`),
  KEY `ix_timetable_lesson_room_id` (`tenant_id`, `room_id`),
  CONSTRAINT `ck_timetable_lesson__lesson_kind` CHECK (`lesson_kind` IN ('lesson', 'lecture', 'tutorial', 'practical', 'live_class', 'registration'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[TIM/config/internal] Recurring scheduled lesson (class or section × subject × teacher × room × cycle slot)';

-- ============================================================================
-- Domain ATT — Attendance registers, absence reporting and follow-up, staff sign-in, visitors and evacuation roll call
-- ============================================================================

CREATE TABLE `absence_contact` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `session_date` DATE NOT NULL,
  `contacted_guardian_id` BINARY(16),
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `message_id` BINARY(16),
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason_given` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `escalated_to` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `attempted_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_absence_contact_tenant` (`tenant_id`),
  CONSTRAINT `ck_absence_contact__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_absence_contact__outcome` CHECK (`outcome` IN ('reached_reason_given', 'reached_no_reason', 'no_answer', 'message_sent', 'failed')),
  CONSTRAINT `ck_absence_contact__escalated_to` CHECK (`escalated_to` IS NULL OR `escalated_to` IN ('pastoral_lead', 'dsl', 'head', 'lga'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/event/confidential] First-day absence contact attempt and outcome (escalation and DSL alert for vulnerable learners not reached)';

CREATE TABLE `absence_report` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `reported_by_guardian_id` BINARY(16),
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `from_date` DATE NOT NULL,
  `to_date` DATE NOT NULL,
  `reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `message_text` VARCHAR(2000) COLLATE utf8mb4_0900_ai_ci,
  `attachment_document_id` BINARY(16) COMMENT 'Medical note',
  `proposed_code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `conversation_id` BINARY(16),
  `handled_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_absence_report_conversation_id` (`tenant_id`, `conversation_id`),
  CONSTRAINT `ck_absence_report__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_absence_report__status` CHECK (`status` IN ('received', 'acknowledged', 'accepted', 'queried', 'rejected')),
  CONSTRAINT `ck_absence_report__dates` CHECK (to_date >= from_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/transaction/confidential] Absence reported by a parent (app, WhatsApp, web, office) — acknowledged, accepted (pre-fills code) or queried';

CREATE TABLE `attendance_mark` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `register_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `session_date` DATE NOT NULL,
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Present, Late, Absent (unauthorised), Medical, Excused, Approved activity, Not required',
  `minutes_late` SMALLINT,
  `reason_source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `absence_report_id` BINARY(16),
  `recorded_by` BINARY(16) NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'teacher, office, kiosk, biometric_device, lms_live_class, parent_prefill',
  `client_op_id` BINARY(16) COMMENT 'Offline idempotency key',
  `device_captured_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`, `session_date`),
  UNIQUE KEY `uq_attendance_mark_register_id_learner_id_session_date` (`tenant_id`, `register_id`, `learner_id`, `session_date`),
  KEY `ix_attendance_mark_learner_id_session_date` (`tenant_id`, `learner_id`, `session_date`),
  CONSTRAINT `ck_attendance_mark__reason_source` CHECK (`reason_source` IS NULL OR `reason_source` IN ('teacher', 'parent', 'office', 'system')),
  CONSTRAINT `ck_attendance_mark__source` CHECK (`source` IN ('teacher', 'office', 'kiosk', 'biometric_device', 'lms_live_class', 'parent_prefill', 'import'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/transaction/confidential] Attendance mark per learner per register (partitioned by month; integrity checked nightly)'
PARTITION BY RANGE COLUMNS (`session_date`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE `attendance_register` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `class_group_id` BINARY(16) NOT NULL,
  `register_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `session_date` DATE NOT NULL,
  `lesson_occurrence_id` BINARY(16) COMMENT 'Lesson registers',
  `due_at` DATETIME(6) NOT NULL COMMENT 'Deadline (missing-register nudge at +10 min, escalation at +30 min)',
  `taken_by_staff_id` BINARY(16),
  `submitted_at` DATETIME(6),
  `device_captured_at` DATETIME(6) COMMENT 'Offline capture time',
  `marks_count` SMALLINT,
  `release_to_parents_at` DATETIME(6) COMMENT 'Live or delayed sharing per institution setting',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `lesson_key` BINARY(16) GENERATED ALWAYS AS (IFNULL(`lesson_occurrence_id`, UNHEX(REPEAT('0', 32)))) STORED COMMENT 'lesson_occurrence_id, or all-zero for daily registers (uniqueness)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_attendance_register_class_group_id_register_kind_ses_0b7befdd` (`tenant_id`, `class_group_id`, `register_kind`, `session_date`, `lesson_key`),
  KEY `ix_attendance_register_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_attendance_register_session_date_status` (`tenant_id`, `session_date`, `status`),
  KEY `ix_attendance_register_lesson_occurrence_id` (`tenant_id`, `lesson_occurrence_id`),
  CONSTRAINT `ck_attendance_register__register_kind` CHECK (`register_kind` IN ('am', 'pm', 'daily', 'lesson', 'activity', 'trip')),
  CONSTRAINT `ck_attendance_register__status` CHECK (`status` IN ('due', 'in_progress', 'submitted', 'late', 'missing', 'corrected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/transaction/internal] Register header — one daily (AM/PM) or lesson register for a class or section on a date';

CREATE TABLE `evacuation_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `campus_id` BINARY(16) NOT NULL,
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `started_at` DATETIME(6) NOT NULL,
  `all_clear_at` DATETIME(6),
  `incident_lead_staff_id` BINARY(16),
  `expected_count` INT UNSIGNED,
  `accounted_count` INT UNSIGNED,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_evacuation_event_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_evacuation_event_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_evacuation_event__kind` CHECK (`kind` IN ('fire', 'drill', 'lockdown', 'invacuation', 'other')),
  CONSTRAINT `ck_evacuation_event__status` CHECK (`status` IN ('in_progress', 'all_clear', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/transaction/internal] Evacuation or drill (start, all-clear, timings as safe-schools inspection evidence)';

CREATE TABLE `evacuation_mark` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `evacuation_event_id` BINARY(16) NOT NULL,
  `person_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `person_id` BINARY(16) NOT NULL,
  `assembly_point` VARCHAR(60) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `marshal_staff_id` BINARY(16) NOT NULL,
  `state` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `marked_at` DATETIME(6) NOT NULL,
  `client_op_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_evacuation_mark_evacuation_event_id_person_kind_pers_8633f6cb` (`tenant_id`, `evacuation_event_id`, `person_kind`, `person_id`, `state`),
  CONSTRAINT `ck_evacuation_mark__person_kind` CHECK (`person_kind` IN ('learner', 'staff', 'visitor')),
  CONSTRAINT `ck_evacuation_mark__state` CHECK (`state` IN ('safe', 'missing', 'absent_today', 'left_site'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/event/confidential] Roll-call mark for a person at an assembly point (learner, staff or visitor), captured offline';

CREATE TABLE `staff_attendance` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_id` BINARY(16) NOT NULL,
  `signed_on` DATE NOT NULL,
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `at` DATETIME(6) NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `device_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`, `signed_on`),
  KEY `ix_staff_attendance_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_staff_attendance__direction` CHECK (`direction` IN ('in', 'out')),
  CONSTRAINT `ck_staff_attendance__source` CHECK (`source` IN ('teacher', 'office', 'kiosk', 'biometric_device', 'lms_live_class', 'parent_prefill', 'import'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ATT/event/confidential] Staff sign-in and sign-out (manual, kiosk or biometric device — templates never leave the device)'
PARTITION BY RANGE COLUMNS (`signed_on`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

