-- ============================================================================
-- Domain ASM — Assessment, grading, moderation, targets, report cards, examinations, results, GPA and transcripts
-- ============================================================================

CREATE TABLE `academic_standing` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `period_id` BINARY(16) NOT NULL,
  `credits_attempted` DECIMAL(6,1) NOT NULL,
  `credits_earned` DECIMAL(6,1) NOT NULL,
  `gpa` DECIMAL(4,2),
  `cgpa` DECIMAL(4,2),
  `progression` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `classification` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `is_borderline` BOOLEAN NOT NULL DEFAULT FALSE,
  `board_decision` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_academic_standing_enrolment_id_period_id` (`tenant_id`, `enrolment_id`, `period_id`),
  CONSTRAINT `ck_academic_standing__progression` CHECK (`progression` IS NULL OR `progression` IN ('progress', 'progress_with_carryover', 'repeat', 'probation', 'withdraw', 'graduate')),
  CONSTRAINT `ck_academic_standing__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] GPA/CGPA, credits, progression and classification per learner per period (borderline cases flagged)';

CREATE TABLE `assessment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `class_subject_plan_id` BINARY(16),
  `course_section_id` BINARY(16),
  `assignment_id` BINARY(16) COMMENT 'LMS assignment that posts its marks here',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `assessment_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `max_mark` DECIMAL(7,3) NOT NULL,
  `weight` DECIMAL(6,3) NOT NULL,
  `assessed_on` DATE,
  `grading_scale_id` BINARY(16),
  `node_ids` JSON COMMENT 'Curriculum objectives assessed (G7)',
  `is_moderated` BOOLEAN NOT NULL DEFAULT FALSE,
  `locked_at` DATETIME(6) COMMENT 'Results locked after approval',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assessment_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_assessment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_assessment_class_subject_plan_id` (`tenant_id`, `class_subject_plan_id`),
  KEY `ix_assessment_course_section_id` (`tenant_id`, `course_section_id`),
  KEY `ix_assessment_assignment_id` (`tenant_id`, `assignment_id`),
  CONSTRAINT `ck_assessment__assessment_kind` CHECK (`assessment_kind` IN ('formative', 'summative', 'coursework', 'practical', 'competency', 'ca_test', 'examination', 'homework', 'quiz')),
  CONSTRAINT `ck_assessment__status` CHECK (`status` IN ('draft', 'open', 'marking', 'moderated', 'approved', 'locked'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/config/internal] Assessment 360 definition (formative, summative, coursework, practical, competency, CA test, examination)';

CREATE TABLE `assessment_result` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `assessment_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `score` DECIMAL(7,3),
  `grade_label` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `objective_results` JSON COMMENT 'Per curriculum objective (curriculum evidence)',
  `is_missing_work` BOOLEAN NOT NULL DEFAULT FALSE,
  `access_arrangement` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci COMMENT 'Applied adjustment (no need detail)',
  `comment` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `entered_by` BINARY(16) NOT NULL,
  `corrected_after_lock` BOOLEAN NOT NULL DEFAULT FALSE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assessment_result_assessment_id_learner_id` (`tenant_id`, `assessment_id`, `learner_id`),
  KEY `ix_assessment_result_learner_id` (`tenant_id`, `learner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] Mark per learner per assessment (hard ≤ max mark; corrections after lock need head approval)';

CREATE TABLE `exam_anomaly` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `series_id` BINARY(16) NOT NULL,
  `anomaly_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evidence` JSON NOT NULL,
  `affected_entry_ids` JSON,
  `assigned_to` BINARY(16),
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_exam_anomaly_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_exam_anomaly_series_id` (`tenant_id`, `series_id`),
  CONSTRAINT `ck_exam_anomaly__anomaly_kind` CHECK (`anomaly_kind` IN ('distribution_shift', 'similarity_cluster', 'improbable_improvement', 'timing', 'other')),
  CONSTRAINT `ck_exam_anomaly__outcome` CHECK (`outcome` IS NULL OR `outcome` IN ('no_issue', 'explained', 'action_taken', 'referred', 'confirmed')),
  CONSTRAINT `ck_exam_anomaly__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/queue/confidential] Statistical anomaly for human review (distribution shift, similarity cluster, improbable improvement) — never auto-penalised';

