) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/config/internal] Teacher marksheet column (yes/no, numeric, grade, date, comment) for offline spreadsheet round-trips';

CREATE TABLE `moderation_sample` (
