  UNIQUE KEY `uq_report_card_run_id_learner_id` (`tenant_id`, `run_id`, `learner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] Published report card of a learner for a period (document stored to the learner record)';

CREATE TABLE `report_card_run` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
