  `published_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_report_card_run_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_report_card_run_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_report_card_run__status` CHECK (`status` IN ('draft', 'previewed', 'running', 'awaiting_approval', 'approved', 'issued', 'completed', 'failed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/internal] Report-card generation run (templates, completeness checks, publication to the parent portal)';

CREATE TABLE `result_import` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `series_id` BINARY(16) NOT NULL,
  `source_document_id` BINARY(16),
  `rows_total` INT UNSIGNED NOT NULL,
  `rows_matched` INT UNSIGNED NOT NULL,
  `rows_in_review` INT UNSIGNED NOT NULL,
  `anomalies` JSON,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_result_import_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_result_import_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_result_import_series_id` (`tenant_id`, `series_id`),
  CONSTRAINT `ck_result_import__status` CHECK (`status` IN ('uploaded', 'mapped', 'validating', 'validated', 'matching', 'staged', 'committed', 'rolled_back', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] Import of results from an exam body (file or API) with candidate matching and anomaly review';

CREATE TABLE `target_grade` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `target_label` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `working_at_label` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `rag` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `gap_points` DECIMAL(6,2),
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_target_grade_tenant_id_id` (`tenant_id`, `id`),
  CONSTRAINT `ck_target_grade__method` CHECK (`method` IN ('prior_attainment', 'tracking_points', 'manual')),
  CONSTRAINT `ck_target_grade__rag` CHECK (`rag` IS NULL OR `rag` IN ('red', 'amber', 'green')),
  CONSTRAINT `ck_target_grade__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] Target grade from prior attainment and tracking points, with RAG progress';

CREATE TABLE `transcript` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `certificate_id` BINARY(16) COMMENT 'Registry record carrying number, hash and signature',
  `document_id` BINARY(16) NOT NULL,
  `content_hash` BINARY(32) NOT NULL,
  `issued_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_transcript_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/transaction/confidential] Digitally signed, verifiable transcript (registered in the certificate registry as a credential of kind transcript)';

-- ============================================================================
-- Domain BEH — Behaviour, rewards, seating plans and influences, intelligence events, detentions, on-call and on-report
-- ============================================================================

CREATE TABLE `badge_award` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `badge_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `awarded_at` DATETIME(6) NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `intel_firing_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_badge_award_badge_id` (`tenant_id`, `badge_id`),
  KEY `ix_badge_award_intel_firing_id` (`tenant_id`, `intel_firing_id`),
  CONSTRAINT `ck_badge_award__source` CHECK (`source` IN ('points_threshold', 'rule', 'staff_award', 'activity'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[BEH/event/confidential] Badge awarded to a learner';

CREATE TABLE `behaviour_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `behaviour_type_id` BINARY(16) NOT NULL,
  `points` SMALLINT NOT NULL COMMENT 'Points of the policy version in force',
  `lesson_occurrence_id` BINARY(16),
  `room_id` BINARY(16),
  `location` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci,
  `occurred_at` DATETIME(6) NOT NULL,
  `recorded_by_staff_id` BINARY(16) NOT NULL,
  `description` VARCHAR(2000) COLLATE utf8mb4_0900_ai_ci,
  `target_learner_ids` JSON COMMENT 'Targets of bullying (routes to the pastoral lead)',
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decision_by` BINARY(16) COMMENT 'Head for outcomes above detention',
  `appeal_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `client_op_id` BINARY(16) COMMENT 'Offline idempotency key',
  `reversed_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_behaviour_event_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_behaviour_event_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_behaviour_event_learner_id_occurred_at` (`tenant_id`, `learner_id`, `occurred_at`),
  KEY `ix_behaviour_event_behaviour_type_id` (`tenant_id`, `behaviour_type_id`),
  KEY `ix_behaviour_event_lesson_occurrence_id` (`tenant_id`, `lesson_occurrence_id`),
  KEY `ix_behaviour_event_room_id` (`tenant_id`, `room_id`),
  CONSTRAINT `ck_behaviour_event__outcome` CHECK (`outcome` IS NULL OR `outcome` IN ('none', 'warning', 'detention', 'on_report', 'parent_contact', 'intervention', 'internal_exclusion', 'suspension', 'exclusion')),
  CONSTRAINT `ck_behaviour_event__appeal_status` CHECK (`appeal_status` IS NULL OR `appeal_status` IN ('none', 'lodged', 'upheld', 'dismissed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[BEH/event/confidential] Behaviour log entry (two taps from register, class list, seating plan or app; online or offline)';

CREATE TABLE `behaviour_policy` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `framework_version` INT UNSIGNED NOT NULL COMMENT 'State framework version it conforms to',
  `version` INT UNSIGNED NOT NULL,
  `missing_homework_is_behaviour` BOOLEAN NOT NULL DEFAULT FALSE,
  `effective_from` DATE NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_behaviour_policy_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_behaviour_policy_institution_id_version` (`tenant_id`, `institution_id`, `version`),
  KEY `ix_behaviour_policy_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_behaviour_policy__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[BEH/config/internal] Versioned behaviour policy of an institution (immutable once published; never re-scores past events)';

CREATE TABLE `behaviour_type` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `policy_id` BINARY(16) NOT NULL,
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `label` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `polarity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'bullying, violence, lateness, positive conduct …',
  `points` SMALLINT NOT NULL,
  `icon` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `default_outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `detention_type_id` BINARY(16),
  `counts_in_reports` BOOLEAN NOT NULL DEFAULT TRUE,
  `counts_in_influences` BOOLEAN NOT NULL DEFAULT TRUE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_behaviour_type_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_behaviour_type_policy_id_code` (`tenant_id`, `policy_id`, `code`),
  KEY `ix_behaviour_type_detention_type_id` (`tenant_id`, `detention_type_id`),
  CONSTRAINT `ck_behaviour_type__polarity` CHECK (`polarity` IN ('positive', 'negative')),
  CONSTRAINT `ck_behaviour_type__default_outcome` CHECK (`default_outcome` IS NULL OR `default_outcome` IN ('none', 'warning', 'detention', 'on_report', 'parent_contact', 'intervention', 'internal_exclusion', 'suspension', 'exclusion'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[BEH/config/internal] Positive or negative behaviour with icon, points, default outcome and use in reports/influences';

CREATE TABLE `detention` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `detention_type_id` BINARY(16) NOT NULL,
  `behaviour_event_id` BINARY(16),
