  `room_id` BINARY(16),
  `supervisor_staff_id` BINARY(16),
  `parent_notified_at` DATETIME(6),
  `transport_checked` BOOLEAN NOT NULL DEFAULT FALSE,
  `minutes_owed` INT NOT NULL,
  `attendance` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_detention_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_detention_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_detention_detention_type_id` (`tenant_id`, `detention_type_id`),
  KEY `ix_detention_behaviour_event_id` (`tenant_id`, `behaviour_event_id`),
  KEY `ix_detention_intel_firing_id` (`tenant_id`, `intel_firing_id`),
  KEY `ix_detention_escalated_from_id` (`tenant_id`, `escalated_from_id`),
  KEY `ix_detention_room_id` (`tenant_id`, `room_id`),
  CONSTRAINT `ck_detention__attendance` CHECK (`attendance` IN ('pending', 'attended', 'not_attended', 'escalated', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[BEH/transaction/confidential] Detention session and attendance (Attended, Pending, Not attended, Escalated)';

CREATE TABLE `detention_type` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Lunchtime, Head of year, Senior leadership',
  `ladder_level` SMALLINT NOT NULL,
  `duration_minutes` INT NOT NULL,
  `default_room_id` BINARY(16),
  `default_supervisor_staff_id` BINARY(16),
  `is_after_school` BOOLEAN NOT NULL DEFAULT FALSE,
  `parent_notice_hours` SMALLINT NOT NULL DEFAULT 24,
  `next_level_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
