) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SEN/transaction/confidential] Intervention with baseline, target, learners, lead, review date and outcome (closed loop)';

