CREATE TABLE `admission_application` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `programme_id` BINARY(16),
  `education_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `learner_id` BINARY(16) COMMENT 'Matched or created at offer acceptance',
  `applicant_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `applicant_dob` DATE,
  `applicant_email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `applicant_phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `answers` JSON NOT NULL,
  `olevel_verification` JSON COMMENT 'Via Certificate 360 or exam-body adapters',
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decided_by` BINARY(16) COMMENT 'Admission refusal is human-only',
  `offer_expires_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_admission_application_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_admission_application_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_admission_application__channel` CHECK (`channel` IN ('online', 'office', 'agent', 'exam_body_adapter', 'import')),
  CONSTRAINT `ck_admission_application__decision` CHECK (`decision` IS NULL OR `decision` IN ('offer', 'conditional_offer', 'waitlist', 'refuse')),
  CONSTRAINT `ck_admission_application__status` CHECK (`status` IN ('draft', 'submitted', 'reviewing', 'assessment', 'decided', 'offer_accepted', 'enrolled', 'declined', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SEC/transaction/confidential] Admission application for a school place or tertiary programme (entry checks, O''Level verification, decisions, offers)';

