  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `instructions` TEXT NOT NULL,
  `node_ids` JSON COMMENT 'Objectives assessed',
  `max_mark` DECIMAL(7,3),
  `rubric_id` BINARY(16),
  `markbook_weight` DECIMAL(6,3),
  `assessment_id` BINARY(16) COMMENT 'Markbook column fed on release',
  `opens_at` DATETIME(6) NOT NULL,
  `due_at` DATETIME(6) NOT NULL,
  `late_policy` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'accept_flag',
  `allow_resubmission` BOOLEAN NOT NULL DEFAULT FALSE,
  `group_settings` JSON,
  `accessibility_options` JSON,
  `ai_policy` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'allowed_with_acknowledgement',
  `release_at` DATETIME(6) COMMENT 'Scheduled release of marks and feedback',
  `homework_reason` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci COMMENT 'Reason given when the nightly homework limit is exceeded',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assignment_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_assignment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_assignment_course_space_id_due_at` (`tenant_id`, `course_space_id`, `due_at`),
  KEY `ix_assignment_unit_id` (`tenant_id`, `unit_id`),
  KEY `ix_assignment_rubric_id` (`tenant_id`, `rubric_id`),
  KEY `ix_assignment_assessment_id` (`tenant_id`, `assessment_id`),
  CONSTRAINT `ck_assignment__assignment_kind` CHECK (`assignment_kind` IN ('homework', 'coursework', 'ca_test', 'quiz_cbt', 'practical', 'portfolio', 'peer_review', 'digital_skills_task')),
  CONSTRAINT `ck_assignment__late_policy` CHECK (`late_policy` IN ('accept_flag', 'accept_with_penalty', 'close_at_due')),
  CONSTRAINT `ck_assignment__ai_policy` CHECK (`ai_policy` IN ('not_allowed', 'allowed_with_acknowledgement', 'encouraged')),
  CONSTRAINT `ck_assignment__status` CHECK (`status` IN ('draft', 'scheduled', 'published', 'closed', 'marked', 'released', 'archived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/transaction/internal] Assignment — homework, coursework, CA test, quiz/CBT, practical, portfolio, peer review or digital-skills task';

