CREATE TABLE `lms_unit` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `course_space_id` BINARY(16) NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `sort_order` SMALLINT NOT NULL,
  `node_ids` JSON,
  `scheme_week_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lms_unit_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_lms_unit_course_space_id` (`tenant_id`, `course_space_id`),
  KEY `ix_lms_unit_scheme_week_id` (`tenant_id`, `scheme_week_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/config/internal] Unit (week or topic) of a course space generated from the scheme of work and tagged to objectives';

CREATE TABLE `originality_report` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `submission_id` BINARY(16) NOT NULL,
  `provider` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `similarity_pct` DECIMAL(6,3),
  `report_ref` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `checked_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_originality_report_submission_id` (`tenant_id`, `submission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/event/confidential] Originality check result from the configured provider (shown to the teacher only; never an automatic penalty)';

CREATE TABLE `question` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `bank_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `item_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `stem` TEXT NOT NULL,
  `options` JSON,
  `answer_key_enc` VARBINARY(1024) COMMENT 'Envelope-encrypted answer_key. Encrypted until the test closes',
  `node_ids` JSON,
  `difficulty` DECIMAL(7,6),
  `discrimination` DECIMAL(5,3),
  `qti_ref` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci COMMENT 'QTI 3.0 identifier',
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_question_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_question__item_kind` CHECK (`item_kind` IN ('single_choice', 'multiple_choice', 'true_false', 'numeric', 'short_text', 'essay', 'matching')),
  CONSTRAINT `ck_question__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/master/internal] Question-bank item owned by a department or the state (with difficulty and discrimination statistics)';

CREATE TABLE `quiz_attempt` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `assignment_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `item_order` JSON NOT NULL,
  `responses` JSON,
  `time_allowed_minutes` INT NOT NULL COMMENT 'Includes authorised extra time',
  `started_at` DATETIME(6) NOT NULL,
  `submitted_at` DATETIME(6),
  `device_log` JSON COMMENT 'Secure mode, IP, device',
  `auto_score` DECIMAL(7,3),
  `invigilator_staff_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_quiz_attempt_assignment_id` (`tenant_id`, `assignment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/transaction/confidential] Online quiz or CBT attempt (randomised items, timing incl. extra-time adjustment, secure-mode, IP and device log)';

CREATE TABLE `rubric` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `criteria` JSON NOT NULL COMMENT 'Criteria, levels, descriptors, points',
  `framework_ref` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Digital-skills framework strand',
  `version` INT UNSIGNED NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rubric_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_rubric_scope` (`tenant_id`, `scope_node_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/config/internal] Marking rubric (criteria and levels; digital-skills rubrics map to the framework)';

CREATE TABLE `submission` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `assignment_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `group_ref` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `version_no` SMALLINT NOT NULL,
  `is_draft` BOOLEAN NOT NULL DEFAULT FALSE,
  `text_body` TEXT,
  `device_submitted_at` DATETIME(6) COMMENT 'Device clock (offline work)',
  `synced_at` DATETIME(6) NOT NULL COMMENT 'Server receipt time',
  `is_late` BOOLEAN NOT NULL COMMENT 'Teacher decides when device and sync times straddle the due time',
  `receipt_hash` BINARY(32) NOT NULL,
  `ai_declaration` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'app, web, scan_split (QR cover sheet), ussd_confirmation',
  `client_op_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_submission_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_submission_receipt_hash` (`tenant_id`, `receipt_hash`),
  UNIQUE KEY `uq_submission_assignment_id_learner_id_version_no` (`tenant_id`, `assignment_id`, `learner_id`, `version_no`),
  CONSTRAINT `ck_submission__ai_declaration` CHECK (`ai_declaration` IN ('none_used', 'used_acknowledged', 'not_declared')),
  CONSTRAINT `ck_submission__source` CHECK (`source` IN ('app', 'web', 'scan_split', 'ussd_confirmation', 'offline_sync'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/transaction/confidential] Learner submission version (hashed, timestamped receipt; device and sync times; AI-use declaration)';

CREATE TABLE `submission_file` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `submission_id` BINARY(16) NOT NULL,
  `object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `mime_type` VARCHAR(127) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `size_bytes` BIGINT NOT NULL,
  `sha256` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_submission_file_submission_id` (`tenant_id`, `submission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/event/confidential] File in a submission (compressed on upload; up to 200 MB per submission, configurable)';

CREATE TABLE `submission_mark` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `submission_id` BINARY(16) NOT NULL,
  `marker_staff_id` BINARY(16) NOT NULL,
  `score` DECIMAL(7,3),
  `rubric_levels` JSON,
  `feedback` TEXT,
  `annotation_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin,
  `audio_feedback_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin,
  `objective_results` JSON,
  `is_auto_marked` BOOLEAN NOT NULL DEFAULT FALSE,
  `released_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_submission_mark_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_submission_mark_submission_id` (`tenant_id`, `submission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/transaction/confidential] Mark and feedback for a submission (rubric, comments, annotations, audio feedback; auto-marked items)';

CREATE TABLE `ussd_session` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16),
  `msisdn_hmac` BINARY(32) NOT NULL,
  `action` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `assignment_id` BINARY(16),
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_ussd_session_assignment_id` (`tenant_id`, `assignment_id`),
  CONSTRAINT `ck_ussd_session__action` CHECK (`action` IN ('list_due', 'confirm_completed', 'help'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LMS/event/confidential] USSD/SMS feature-phone interaction (due dates, completion confirmation)';

-- ============================================================================
-- Domain COM — Communication — messaging gateway, WhatsApp and Zenzap, templates, conversations, broadcasts, notifications, announcements and consent requests
-- ============================================================================

CREATE TABLE `announcement_recipient` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `announcement_id` BINARY(16) NOT NULL,
  `user_id` BINARY(16) NOT NULL,
  `delivered_at` DATETIME(6),
  `read_at` DATETIME(6),
  `acknowledged_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_announcement_recipient_announcement_id_user_id` (`tenant_id`, `announcement_id`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/link/internal] Delivery, read and acknowledgement per announcement recipient';

CREATE TABLE `broadcast_campaign` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `audience_rule` JSON NOT NULL,
  `template_id` BINARY(16) NOT NULL,
  `scheduled_at` DATETIME(6),
  `throttle_per_second` SMALLINT,
  `recipients_estimated` INT UNSIGNED,
  `cost_estimate_minor` BIGINT COMMENT 'Counts only template messages outside open service windows (minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `results` JSON,
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_broadcast_campaign_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_broadcast_campaign_template_id` (`tenant_id`, `template_id`),
  CONSTRAINT `ck_broadcast_campaign__status` CHECK (`status` IN ('draft', 'awaiting_approval', 'scheduled', 'sending', 'completed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/internal] Broadcast campaign (audience rules, scheduling, language variants, throttling, cost estimate, results)';

CREATE TABLE `channel_contact` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `person_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `person_id` BINARY(16) NOT NULL,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `endpoint_hmac` BINARY(32) NOT NULL COMMENT 'HMAC-SHA-256 lookup of endpoint',
  `endpoint_enc` VARBINARY(1024) NOT NULL COMMENT 'Envelope-encrypted endpoint. E.164 phone, e-mail or device token',
  `endpoint_last4` CHAR(4) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Last four characters of endpoint for masked display',
  `is_verified` BOOLEAN NOT NULL DEFAULT FALSE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_channel_contact_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_channel_contact_channel_endpoint_hmac` (`tenant_id`, `channel`, `endpoint_hmac`),
  CONSTRAINT `ck_channel_contact__person_kind` CHECK (`person_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_channel_contact__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/master/confidential] Contact endpoint of a person on a channel (phone or address) with HMAC lookup for inbound matching';

CREATE TABLE `channel_opt_in` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `contact_id` BINARY(16) NOT NULL,
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `wording` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Wording shown at opt-in',
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `decided_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_channel_opt_in_contact_id` (`tenant_id`, `contact_id`),
  CONSTRAINT `ck_channel_opt_in__decision` CHECK (`decision` IN ('opt_in', 'opt_out')),
  CONSTRAINT `ck_channel_opt_in__category` CHECK (`category` IS NULL OR `category` IN ('utility', 'authentication', 'marketing', 'service', 'internal')),
  CONSTRAINT `ck_channel_opt_in__source` CHECK (`source` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/event/confidential] Opt-in / opt-out per contact and channel with evidence (STOP honoured immediately)';

CREATE TABLE `consent_request` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `consent_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `body` TEXT NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `learner_ids` JSON NOT NULL COMMENT 'Learners covered',
  `respond_by` DATETIME(6),
  `trip_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_consent_request_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_consent_request_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_consent_request_trip_id` (`tenant_id`, `trip_id`),
  CONSTRAINT `ck_consent_request__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/internal] Request for parental consent (trip, photographs, event, data sharing) — versioned, reminders only to pending parents';

CREATE TABLE `conversation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `channel_id` BINARY(16) NOT NULL,
  `contact_id` BINARY(16),
  `external_thread_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
  `linked_record_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'alert, coverage_gap, corrective_action, inspection, reissue_case',
  `linked_record_id` BINARY(16),
  `assigned_office` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `assigned_user_id` BINARY(16),
  `service_window_ends_at` DATETIME(6) COMMENT 'WhatsApp 24-hour customer-service window',
  `sla_due_at` DATETIME(6),
  `is_bot_handled` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Parent Concierge Agent; hand-over offered',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_conversation_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_conversation_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_conversation_channel_id` (`tenant_id`, `channel_id`),
  KEY `ix_conversation_contact_id` (`tenant_id`, `contact_id`),
  CONSTRAINT `ck_conversation__assigned_office` CHECK (`assigned_office` IS NULL OR `assigned_office` IN ('class_teacher', 'bursary', 'admissions', 'pastoral', 'attendance', 'helpdesk', 'head')),
  CONSTRAINT `ck_conversation__status` CHECK (`status` IN ('open', 'pending', 'resolved', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/confidential] Two-way conversation thread (WhatsApp inbox, workspace thread linked to a record, web chat)';

CREATE TABLE `mail_merge_job` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `template_id` BINARY(16) NOT NULL,
  `recipient_rule` JSON NOT NULL,
  `output` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `documents_created` INT UNSIGNED,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_mail_merge_job_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_mail_merge_job_template_id` (`tenant_id`, `template_id`),
  CONSTRAINT `ck_mail_merge_job__output` CHECK (`output` IN ('letters_pdf', 'labels', 'badges', 'email')),
  CONSTRAINT `ck_mail_merge_job__status` CHECK (`status` IN ('draft', 'previewed', 'running', 'awaiting_approval', 'approved', 'issued', 'completed', 'failed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/confidential] Mail-merge run producing letters, labels or badges (every letter stored to the recipient record)';

CREATE TABLE `message` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `created_on` DATE NOT NULL COMMENT 'Partition key (UTC date of creation)',
  `conversation_id` BINARY(16),
  `campaign_id` BINARY(16),
  `notification_id` BINARY(16),
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `recipient_id` BINARY(16),
  `about_learner_id` BINARY(16),
  `template_id` BINARY(16),
  `language` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin,
  `body` TEXT COMMENT 'Rendered content (never special-category on external channels)',
  `priority` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'normal',
  `estimated_cost_minor` BIGINT COMMENT '(minor units)',
  `actual_cost_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `provider_message_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
  `delivery_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `delivered_at` DATETIME(6),
  `read_at` DATETIME(6),
  `failure_reason` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci,
  `sent_by` BINARY(16) COMMENT 'User or agent service identity',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`, `created_on`),
  KEY `ix_message_recipient_kind_recipient_id` (`tenant_id`, `recipient_kind`, `recipient_id`),
  KEY `ix_message_provider_message_ref` (`tenant_id`, `provider_message_ref`),
  CONSTRAINT `ck_message__direction` CHECK (`direction` IN ('outbound', 'inbound')),
  CONSTRAINT `ck_message__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_message__recipient_kind` CHECK (`recipient_kind` IS NULL OR `recipient_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_message__priority` CHECK (`priority` IN ('p1', 'high', 'normal', 'low')),
  CONSTRAINT `ck_message__delivery_status` CHECK (`delivery_status` IN ('queued', 'sent', 'delivered', 'read', 'failed', 'retrying', 'abandoned', 'processed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/confidential] Message sent or received on any channel (delivery, read, failure status; stored against the recipient record)'
PARTITION BY RANGE COLUMNS (`created_on`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE `message_channel` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `provider` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'meta_cloud_api, bsp_name, zenzap, teams, slack, smpp_aggregator …',
  `display_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `address` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'E.164 number, sender id, workspace id',
  `credentials_vault_ref` VARCHAR(255) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Token stored in the vault; never in the database',
  `monthly_spend_cap_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `quiet_hours` JSON COMMENT 'Default 20:00–07:00 local',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_message_channel_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_message_channel_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_message_channel__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_message_channel__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/config/internal] Connected channel (WhatsApp number, Zenzap workspace, SMS sender ID, e-mail domain, push app) held by the tenant';

CREATE TABLE `message_template` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `channel_id` BINARY(16),
  `template_key` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `variants` JSON NOT NULL COMMENT 'Language → body with merge fields',
  `provider_template_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
  `approval_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `is_mail_merge` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Word-compatible letter/label/badge template',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_message_template_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_message_template_scope_node_id_template_key_version` (`tenant_id`, `scope_node_id`, `template_key`, `version`),
  KEY `ix_message_template_channel_id` (`tenant_id`, `channel_id`),
  CONSTRAINT `ck_message_template__category` CHECK (`category` IN ('utility', 'authentication', 'marketing', 'service', 'internal')),
  CONSTRAINT `ck_message_template__approval_status` CHECK (`approval_status` IN ('draft', 'submitted', 'approved', 'rejected', 'paused', 'retired')),
  CONSTRAINT `ck_message_template__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/config/internal] Approved message template (Meta category, multilingual variants, approval status, version)';

CREATE TABLE `notification` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
