  `event_id` BINARY(16) COMMENT 'Source domain event',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `body` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci COMMENT 'Never special-category content',
  `link` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `priority` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `read_at` DATETIME(6),
