  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`, `created_on`),
  KEY `ix_notification_user_id_read_at` (`tenant_id`, `user_id`, `read_at`),
  CONSTRAINT `ck_notification__priority` CHECK (`priority` IN ('p1', 'high', 'normal', 'low'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/internal] In-app notification to a user (permission-trimmed; may fan out to external channels)'
PARTITION BY RANGE COLUMNS (`created_on`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE `notification_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `event_type` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_rule` JSON NOT NULL,
  `channel_policy` JSON NOT NULL,
  `is_digest` BOOLEAN NOT NULL DEFAULT FALSE,
  `bypass_quiet_hours` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Priority 1 and DSL safeguarding only',
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_notification_rule_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_notification_rule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/config/internal] Rule turning domain events into notifications (recipients, channel policy, digest, quiet hours, escalation)';

CREATE TABLE `staff_announcement` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `body` TEXT NOT NULL,
  `audience_rule` JSON NOT NULL COMMENT 'e.g. timetabled_teachers_of(learner)',
  `requires_acknowledgement` BOOLEAN NOT NULL DEFAULT FALSE,
  `expires_at` DATETIME(6),
  `published_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_announcement_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_staff_announcement_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_staff_announcement__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/transaction/internal] Announcement to staff or parents with relationship-based audience (timetabled teachers, heads of year, tutors), receipts and expiry';

CREATE TABLE `workspace_channel` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `channel_id` BINARY(16) NOT NULL,
  `external_channel_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `audience` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `membership_rule` JSON NOT NULL COMMENT 'Derived from grants and posts; removed automatically on leaving',
  `last_synced_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_workspace_channel_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_workspace_channel_channel_id` (`tenant_id`, `channel_id`),
  CONSTRAINT `ck_workspace_channel__audience` CHECK (`audience` IN ('state_heads', 'lga_heads', 'all_staff', 'department', 'year_group', 'committee')),
  CONSTRAINT `ck_workspace_channel__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[COM/config/internal] Workspace-messaging channel provisioned from the hierarchy and staff posts (state, LGA, institution, department, year group)';

-- ============================================================================
-- Domain FIN — Billing, payments, funding, ledger, budgets, procurement and suppliers
-- ============================================================================

CREATE TABLE `account` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `account_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `holder_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `holder_id` BINARY(16) COMMENT 'learner, family, sponsor or funder',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `gl_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'asset, liability, income, expense, equity (GL accounts)',
  `virtual_account_number` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Per-family virtual account for transfers',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_account_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_account_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  KEY `ix_account_holder_kind_holder_id` (`tenant_id`, `holder_kind`, `holder_id`),
  CONSTRAINT `ck_account__account_kind` CHECK (`account_kind` IN ('learner', 'family', 'sponsor', 'funder', 'general_ledger')),
  CONSTRAINT `ck_account__holder_kind` CHECK (`holder_kind` IS NULL OR `holder_kind` IN ('learner', 'family', 'guardian', 'sponsor', 'funder', 'government', 'employer', 'institution')),
  CONSTRAINT `ck_account__gl_type` CHECK (`gl_type` IS NULL OR `gl_type` IN ('asset', 'liability', 'income', 'expense', 'equity')),
  CONSTRAINT `ck_account__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/master/restricted] Ledger account — learner, family, sponsor or funder account, and general-ledger accounts';

CREATE TABLE `bank_statement_line` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `bank_account_ref` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `statement_date` DATE NOT NULL,
  `value_date` DATE NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `narrative` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `bank_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `matched_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `matched_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bank_statement_line_bank_account_ref_bank_ref` (`tenant_id`, `bank_account_ref`, `bank_ref`),
  KEY `ix_bank_statement_line_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_bank_statement_line__status` CHECK (`status` IN ('unmatched', 'matched', 'part_matched', 'disputed', 'reconciled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Imported bank statement line (MT940/CSV/open banking) reconciled to payments and disbursements';

CREATE TABLE `billing_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `rule_key` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `charge_type_id` BINARY(16) NOT NULL,
  `billing_basis` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `conditions` JSON NOT NULL COMMENT 'Institution, campus, programme, course, level, category, residency, scholarship, family …',
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `priority` SMALLINT NOT NULL,
  `discount_policy` JSON COMMENT 'Sibling/family discounts and stacking',
  `version` INT UNSIGNED NOT NULL,
  `effective_from` DATE NOT NULL,
  `effective_to` DATE,
  `test_results` JSON COMMENT 'Results against sample learners',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_billing_rule_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_billing_rule_scope_node_id_rule_key_version` (`tenant_id`, `scope_node_id`, `rule_key`, `version`),
  KEY `ix_billing_rule_charge_type_id` (`tenant_id`, `charge_type_id`),
  CONSTRAINT `ck_billing_rule__billing_basis` CHECK (`billing_basis` IN ('term', 'semester', 'annual', 'monthly', 'weekly', 'course', 'credit', 'module', 'session', 'hour', 'exam', 'registration', 'learner', 'family', 'service', 'subscription', 'pay_as_you_go')),
  CONSTRAINT `ck_billing_rule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/config/internal] Versioned, effective-dated billing rule (conditions, amount, priority, discount stacking); tested before publishing';

CREATE TABLE `billing_run` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
