  `learners_in_scope` INT UNSIGNED NOT NULL,
  `exceptions` JSON,
  `total_amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `approved_by` BINARY(16),
  `issued_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_billing_run_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_billing_run_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_billing_run__billing_basis` CHECK (`billing_basis` IN ('term', 'semester', 'annual', 'monthly', 'weekly', 'course', 'credit', 'module', 'session', 'hour', 'exam', 'registration', 'learner', 'family', 'service', 'subscription', 'pay_as_you_go')),
  CONSTRAINT `ck_billing_run__status` CHECK (`status` IN ('draft', 'previewed', 'running', 'awaiting_approval', 'approved', 'issued', 'completed', 'failed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/internal] Billing run with preview, exceptions, approval and issue (no duplicate invoice per learner per period)';

CREATE TABLE `budget` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
