  UNIQUE KEY `uq_budget_scope_node_id_fiscal_year_version` (`tenant_id`, `scope_node_id`, `fiscal_year`, `version`),
  CONSTRAINT `ck_budget__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/internal] Budget by cost centre and account linked to enrolment and staffing forecasts (approved via workflow)';

CREATE TABLE `charge_type` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
