  UNIQUE KEY `uq_charge_type_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  KEY `ix_charge_type_income_account_id` (`tenant_id`, `income_account_id`),
  CONSTRAINT `ck_charge_type__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/config/internal] Charge type (tuition, registration, exam, accommodation, transport, meals, uniform, books, ICT, lab, clinical, trips …) with GL account and tax treatment';

CREATE TABLE `credit_note` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
