  KEY `ix_credit_note_invoice_id` (`tenant_id`, `invoice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Credit note against an invoice';

CREATE TABLE `fiscal_period` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'YYYY-MM',
  `starts_on` DATE NOT NULL,
  `ends_on` DATE NOT NULL,
  `closed_at` DATETIME(6),
  `closed_by` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fiscal_period_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_fiscal_period_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/config/internal] Fiscal period (open/closed); closed periods accept no postings';

CREATE TABLE `funding_award` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `funding_source_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `awarded_by` BINARY(16) NOT NULL,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_funding_award_funding_source_id` (`tenant_id`, `funding_source_id`),
  CONSTRAINT `ck_funding_award__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Funding awarded to a learner (scholarship, bursary, capitation share) — never double counted';

CREATE TABLE `funding_source` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `funding_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `funder_account_id` BINARY(16),
  `budget_minor` BIGINT COMMENT '(minor units)',
  `per_learner_cap_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `priority` SMALLINT NOT NULL,
  `eligibility_rule` JSON,
  `valid_until` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_funding_source_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_funding_source_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_funding_source_funder_account_id` (`tenant_id`, `funder_account_id`),
  CONSTRAINT `ck_funding_source__funding_kind` CHECK (`funding_kind` IN ('government', 'capitation', 'scholarship', 'bursary', 'grant', 'sponsorship', 'employer', 'loan', 'instalment')),
  CONSTRAINT `ck_funding_source__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/master/internal] Scholarship, bursary, grant, sponsor, capitation, employer funding or loan (budget and per-learner caps)';

CREATE TABLE `fx_rate` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `rate_date` DATE NOT NULL,
  `base_currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `quote_currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `rate` DECIMAL(18,8) NOT NULL,
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fx_rate_rate_date_base_currency_quote_currency_source` (`tenant_id`, `rate_date`, `base_currency`, `quote_currency`, `source`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/reference/public] Exchange rate captured per source and day (local and reporting currency)';

CREATE TABLE `government_funding_receipt` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `funding_source_id` BINARY(16) NOT NULL,
  `tranche_label` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `amount_due_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `amount_received_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `received_on` DATE,
  `learners_funded` INT UNSIGNED,
  `reconciliation` JSON COMMENT 'Government + student + scholarship + sponsor = total, no double counting',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_government_funding_receipt_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_government_funding_receipt_funding_source_id` (`tenant_id`, `funding_source_id`),
  CONSTRAINT `ck_government_funding_receipt__status` CHECK (`status` IN ('unmatched', 'matched', 'part_matched', 'disputed', 'reconciled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/internal] Capitation or government grant tranche received, reconciled against learners funded';

CREATE TABLE `invoice` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `invoice_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `billing_run_id` BINARY(16),
  `account_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16),
  `payer_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payer_id` BINARY(16) NOT NULL,
  `period_label` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin,
  `issued_on` DATE NOT NULL,
  `due_on` DATE NOT NULL,
  `total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `balance_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fx_rate_to_reporting` DECIMAL(18,8) COMMENT 'Rate captured per transaction',
  `content_hash` BINARY(32) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dedupe_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(`learner_id` IS NULL OR `period_label` IS NULL OR `status` = 'void', NULL, CONCAT(HEX(`learner_id`), ':', `period_label`, ':', HEX(`account_id`)))) STORED COMMENT 'learner:period:run — prevents duplicate invoices per learner per period',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_invoice_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_invoice_invoice_number` (`tenant_id`, `invoice_number`),
  UNIQUE KEY `uq_invoice_dedupe_key` (`tenant_id`, `dedupe_key`),
  KEY `ix_invoice_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_invoice_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_invoice_due_on_status` (`tenant_id`, `due_on`, `status`),
  KEY `ix_invoice_billing_run_id` (`tenant_id`, `billing_run_id`),
  KEY `ix_invoice_account_id` (`tenant_id`, `account_id`),
  CONSTRAINT `ck_invoice__payer_kind` CHECK (`payer_kind` IN ('learner', 'family', 'guardian', 'sponsor', 'funder', 'government', 'employer', 'institution')),
  CONSTRAINT `ck_invoice__status` CHECK (`status` IN ('draft', 'issued', 'part_paid', 'paid', 'overdue', 'credited', 'void'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Invoice to a payer (immutable once issued; credit notes for changes)';

CREATE TABLE `invoice_line` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `invoice_id` BINARY(16) NOT NULL,
  `line_no` SMALLINT NOT NULL,
  `charge_type_id` BINARY(16) NOT NULL,
  `billing_rule_id` BINARY(16),
  `rule_version` INT UNSIGNED,
  `description` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `gross_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `discount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `funded_minor` BIGINT NOT NULL COMMENT 'Applied funding sources (no double funding) (minor units)',
  `net_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_invoice_line_invoice_id_line_no` (`tenant_id`, `invoice_id`, `line_no`),
  KEY `ix_invoice_line_charge_type_id` (`tenant_id`, `charge_type_id`),
  KEY `ix_invoice_line_billing_rule_id` (`tenant_id`, `billing_rule_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Invoice line (charge, rule version used, discount and funding applied)';

CREATE TABLE `journal` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `journal_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fiscal_period_id` BINARY(16) NOT NULL,
  `description` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `posted_by` BINARY(16) NOT NULL,
  `exported_at` DATETIME(6) COMMENT 'Exported to an external ERP/IFMIS where it is the ledger of record',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_journal_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_journal_journal_number` (`tenant_id`, `journal_number`),
  KEY `ix_journal_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_journal_fiscal_period_id` (`tenant_id`, `fiscal_period_id`),
  CONSTRAINT `ck_journal__status` CHECK (`status` IN ('draft', 'posted', 'reversed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Journal (balanced set of ledger entries) in a fiscal period';

CREATE TABLE `ledger_entry` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `journal_id` BINARY(16) NOT NULL,
  `account_id` BINARY(16) NOT NULL,
  `posted_on` DATE NOT NULL,
  `debit_minor` BIGINT NOT NULL DEFAULT 0 COMMENT '(minor units)',
  `credit_minor` BIGINT NOT NULL DEFAULT 0 COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'invoice, payment, payroll_run, credit_note, journal',
  `source_id` BINARY(16) NOT NULL,
  `rule_versions` JSON COMMENT 'Billing rule versions referenced',
  `reverses_id` BINARY(16) COMMENT 'Entry this one reverses',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`, `posted_on`),
  KEY `ix_ledger_entry_account_id_posted_on` (`tenant_id`, `account_id`, `posted_on`),
  CONSTRAINT `ck_ledger_entry__one_side` CHECK ((debit_minor = 0) <> (credit_minor = 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/event/restricted] Double-entry posting (append-only; reverse, never edit; partitioned by month)'
PARTITION BY RANGE COLUMNS (`posted_on`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE `payment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `gateway` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `gateway_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Hard duplicate check',
  `payer_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `payer_contact_hmac` BINARY(32) COMMENT 'Soft duplicate check (payer + amount within 10 minutes)',
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fx_rate_to_reporting` DECIMAL(18,8),
  `received_at` DATETIME(6) NOT NULL,
  `confirmed_at` DATETIME(6),
  `receipt_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `allocation_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `possible_duplicate_of_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payment_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_payment_gateway_ref` (`tenant_id`, `gateway_ref`),
  UNIQUE KEY `uq_payment_receipt_number` (`tenant_id`, `receipt_number`),
  KEY `ix_payment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_payment_possible_duplicate_of_id` (`tenant_id`, `possible_duplicate_of_id`),
  CONSTRAINT `ck_payment__method` CHECK (`method` IN ('bank_transfer', 'virtual_account', 'card', 'direct_debit', 'mobile_money', 'ussd', 'gateway', 'remita', 'cash', 'cheque', 'government', 'employer', 'scholarship')),
  CONSTRAINT `ck_payment__allocation_status` CHECK (`allocation_status` IN ('unallocated', 'suggested', 'part_allocated', 'allocated')),
  CONSTRAINT `ck_payment__status` CHECK (`status` IN ('pending', 'confirmed', 'failed', 'refunded', 'held_duplicate'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Incoming payment (gateway, virtual account, transfer, card, USSD, mobile money, cash, cheque, government, employer, scholarship)';

CREATE TABLE `payment_allocation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `payment_id` BINARY(16) NOT NULL,
  `invoice_id` BINARY(16) NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `confidence` DECIMAL(7,6) COMMENT 'Fee Agent allocates only ≥ 0.95; below that it suggests',
  `allocated_by` BINARY(16) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_payment_allocation_payment_id` (`tenant_id`, `payment_id`),
  KEY `ix_payment_allocation_invoice_id` (`tenant_id`, `invoice_id`),
  CONSTRAINT `ck_payment_allocation__method` CHECK (`method` IN ('virtual_account', 'reference', 'payer_contact', 'heuristic', 'manual'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Allocation of a payment to an invoice (virtual account → reference → payer → heuristic suggestion)';

CREATE TABLE `payment_plan` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `account_id` BINARY(16) NOT NULL,
  `instalments` JSON NOT NULL,
  `hardship_assessment` MEDIUMBLOB COMMENT 'Household circumstances (encrypted)',
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_payment_plan_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_payment_plan_account_id` (`tenant_id`, `account_id`),
  CONSTRAINT `ck_payment_plan__status` CHECK (`status` IN ('draft', 'active', 'under_review', 'completed', 'closed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/restricted] Payment plan and hardship assessment under the ethical recovery policy';

CREATE TABLE `purchase_order` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `po_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `requisition_id` BINARY(16),
  `supplier_id` BINARY(16) NOT NULL,
  `total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `received_on` DATE,
  `supplier_invoice_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `match_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `paid_journal_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_purchase_order_po_number` (`tenant_id`, `po_number`),
  KEY `ix_purchase_order_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_purchase_order_requisition_id` (`tenant_id`, `requisition_id`),
  KEY `ix_purchase_order_supplier_id` (`tenant_id`, `supplier_id`),
  KEY `ix_purchase_order_paid_journal_id` (`tenant_id`, `paid_journal_id`),
  CONSTRAINT `ck_purchase_order__match_status` CHECK (`match_status` IN ('pending', 'matched', 'mismatch', 'override_approved')),
  CONSTRAINT `ck_purchase_order__status` CHECK (`status` IN ('draft', 'approved', 'issued', 'received', 'invoiced', 'paid', 'closed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/internal] Purchase order, goods receipt and three-way match to the supplier invoice';

CREATE TABLE `recovery_policy` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `version` INT UNSIGNED NOT NULL,
  `steps` JSON NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_recovery_policy_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_recovery_policy__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn')),
  CONSTRAINT `ck_recovery_policy__no_core_restriction` CHECK (JSON_SEARCH(`steps`, 'one', 'restrict_core_education') IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/config/internal] Ethical recovery policy (reminder cadence, payment-plan offers); core education restrictions cannot be configured';

CREATE TABLE `requisition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `requisition_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `requested_by` BINARY(16) NOT NULL,
  `cost_centre` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `line_items` JSON NOT NULL,
  `total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `split_purchase_flag` BOOLEAN NOT NULL DEFAULT FALSE,
  `workflow_instance_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_requisition_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_requisition_requisition_number` (`tenant_id`, `requisition_number`),
  KEY `ix_requisition_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_requisition_workflow_instance_id` (`tenant_id`, `workflow_instance_id`),
  CONSTRAINT `ck_requisition__status` CHECK (`status` IN ('draft', 'submitted', 'in_review', 'approved', 'rejected', 'cancelled', 'fulfilled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/transaction/internal] Purchase requisition (delegated approval limits; split-purchase detection)';

CREATE TABLE `supplier` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cac_number` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin,
  `tin` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin,
  `contacts` JSON,
  `bank_account_enc` VARBINARY(1024) COMMENT 'Envelope-encrypted bank_account.',
  `bank_account_last4` CHAR(4) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Last four characters of bank_account for masked display',
  `bank_change_verified_by` BINARY(16),
  `bank_change_approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_supplier_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_supplier_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_supplier__status` CHECK (`status` IN ('active', 'inactive', 'retired')),
  CONSTRAINT `ck_supplier__dual_control` CHECK (bank_change_approved_by IS NULL OR bank_change_verified_by IS NULL OR bank_change_approved_by <> bank_change_verified_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/master/confidential] Supplier 360 master (duplicate detection; call-back verification and dual approval for bank-detail changes)';

CREATE TABLE `tax_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `tax_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `rate` DECIMAL(6,3) NOT NULL,
  `applies_to` JSON NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `effective_from` DATE NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tax_rule_tax_code_version` (`tenant_id`, `tax_code`, `version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FIN/config/public] Tax rule (VAT 7.5% where applicable, withholding) by charge type and jurisdiction';

-- ============================================================================
-- Domain OPS — Operations — estate, rooms, assets, maintenance, safety incidents, capital plan, transport, clubs, trips, meals, library and learning resources
-- ============================================================================

CREATE TABLE `activity` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `activity_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `eligibility_rule` JSON,
  `capacity` SMALLINT,
  `fee_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `allocation_method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `period_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
