  PRIMARY KEY (`id`),
  KEY `ix_dietary_requirement_tenant` (`tenant_id`),
  CONSTRAINT `ck_dietary_requirement__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[OPS/master/confidential] Learner dietary requirement (allergy detail is health data — kept as a coded flag here)';

