) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[OPS/event/internal] Meals served per day and session (school feeding programme numbers reconciled against attendance)';

CREATE TABLE `resource_issue` (
