) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[OPS/event/confidential] Issue, return, loss and condition of a learning resource per learner or class';

CREATE TABLE `room` (
