CREATE TABLE `transport_allocation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `route_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `stop_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_transport_allocation_route_id_learner_id_direction_valid_from` (`tenant_id`, `route_id`, `learner_id`, `direction`, `valid_from`),
  CONSTRAINT `ck_transport_allocation__direction` CHECK (`direction` IN ('to_school', 'from_school')),
  CONSTRAINT `ck_transport_allocation__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[OPS/link/confidential] Learner allocated to a route and stop (detention transport check uses it)';

