-- ============================================================================
-- Domain FRM — Forms and Daybook engine and parents' meetings
-- ============================================================================

CREATE TABLE `form_definition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `field_schema` JSON NOT NULL COMMENT 'Fields, mandatory and conditional rules',
  `raised_by_roles` JSON NOT NULL COMMENT 'Staff, learners, parents, on behalf',
  `confidentiality` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `workflow_definition_id` BINARY(16),
  `cost_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `requires_payment_before_continue` BOOLEAN NOT NULL DEFAULT FALSE,
  `files_to` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `is_template_library` BOOLEAN NOT NULL DEFAULT FALSE,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_form_definition_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  CONSTRAINT `ck_form_definition__confidentiality` CHECK (`confidentiality` IN ('public', 'internal', 'confidential', 'restricted', 'special')),
  CONSTRAINT `ck_form_definition__files_to` CHECK (`files_to` IN ('learner', 'staff', 'family', 'institution')),
  CONSTRAINT `ck_form_definition__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FRM/config/internal] Form template (versioned; text, number, date, choice, signature, upload, body-map, cost and table fields)';

CREATE TABLE `form_response` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `form_id` BINARY(16),
  `form_version` INT UNSIGNED NOT NULL,
  `subject_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `submitted_by` BINARY(16) NOT NULL,
  `on_behalf_of` BINARY(16),
  `answers` JSON NOT NULL,
  `attachment_document_ids` JSON,
  `invoice_id` BINARY(16),
  `workflow_instance_id` BINARY(16),
  `submitted_at` DATETIME(6) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_form_response_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_form_response_subject_kind_subject_id` (`tenant_id`, `subject_kind`, `subject_id`),
  KEY `ix_form_response_invoice_id` (`tenant_id`, `invoice_id`),
  KEY `ix_form_response_workflow_instance_id` (`tenant_id`, `workflow_instance_id`),
  CONSTRAINT `ck_form_response__subject_kind` CHECK (`subject_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_form_response__status` CHECK (`status` IN ('draft', 'submitted', 'in_workflow', 'awaiting_payment', 'approved', 'rejected', 'filed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FRM/transaction/confidential] Submitted form (keeps the version it was submitted on; filed to the Daybook timeline)';

CREATE TABLE `meeting_booking` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `meeting_event_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `guardian_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `mode` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `interpreter_language` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin,
  `video_room_ref` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `recording_consent_all` BOOLEAN NOT NULL DEFAULT FALSE,
  `attended` BOOLEAN,
  `note` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_meeting_booking_meeting_event_id_staff_id_starts_at` (`tenant_id`, `meeting_event_id`, `staff_id`, `starts_at`),
  CONSTRAINT `ck_meeting_booking__mode` CHECK (`mode` IN ('in_person', 'video', 'hybrid')),
  CONSTRAINT `ck_meeting_booking__status` CHECK (`status` IN ('requested', 'confirmed', 'declined', 'cancelled', 'completed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FRM/transaction/confidential] Booked slot for a parent with a teacher (clash prevention; interpreter; attendance and notes to the learner timeline)';

CREATE TABLE `meeting_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `class_group_ids` JSON NOT NULL,
  `days` JSON NOT NULL COMMENT 'Dates and session windows',
  `slot_minutes` SMALLINT NOT NULL,
  `travel_gap_minutes` SMALLINT NOT NULL DEFAULT 5,
  `modes` JSON NOT NULL COMMENT 'in_person, video, hybrid',
  `booking_opens_at` DATETIME(6) NOT NULL,
  `booking_closes_at` DATETIME(6) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_meeting_event_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_meeting_event_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_meeting_event__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FRM/config/internal] Parents'' meeting event across one or more days (in-person, video and hybrid slots per teacher)';

-- ============================================================================
-- Domain INT — Intelligence and automation — alerts, investigations, improvement, recommendations, early warning, model register, agents, assistant and planning
-- ============================================================================

CREATE TABLE `agent` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `template_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `template_version` INT UNSIGNED NOT NULL,
  `service_identity_id` BINARY(16) NOT NULL COMMENT 'Registry service identity',
  `owner_user_id` BINARY(16) NOT NULL,
  `level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `state_max_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Institutions may only lower',
  `triggers` JSON NOT NULL,
  `limits` JSON NOT NULL COMMENT 'Messages, cost, records touched per day',
  `sandbox_result` JSON COMMENT 'Simulation against last month''s data',
  `approved_by` BINARY(16),
  `head_approved_by` BINARY(16) COMMENT 'Required for A2 and above',
  `next_reapproval_on` DATE COMMENT 'Quarterly',
  `error_rate` DECIMAL(7,6),
  `paused_at` DATETIME(6),
  `paused_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_agent_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_agent__level` CHECK (`level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent__state_max_level` CHECK (`state_max_level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent__status` CHECK (`status` IN ('draft', 'sandbox', 'awaiting_approval', 'active', 'paused', 'level_lowered', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Configured automation agent (owner, service identity, level, scope, limits, approval, status)';

CREATE TABLE `agent_action` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `agent_id` BINARY(16) NOT NULL,
  `owner_user_id` BINARY(16) NOT NULL,
  `trigger_detail` JSON NOT NULL,
  `evidence` JSON NOT NULL,
  `rule_applied` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `tool` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `parameters` JSON NOT NULL COMMENT 'Typed, validated parameters (retrieved text is never executed)',
  `level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `explanation` TEXT NOT NULL,
  `undo_until` DATETIME(6) COMMENT '24-hour undo for reversible A2 actions',
  `undone_action_id` BINARY(16) COMMENT 'Undo record for a previous action',
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`, `occurred_at`),
  KEY `ix_agent_action_tenant` (`tenant_id`),
  CONSTRAINT `ck_agent_action__level` CHECK (`level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent_action__outcome` CHECK (`outcome` IN ('proposed', 'executed', 'held_paused', 'refused_policy', 'failed', 'undone'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/event/internal] Action taken or proposed by an agent — trigger, evidence, rule, tool call, outcome, owner ("Agent X for Owner Y"); append-only'
PARTITION BY RANGE COLUMNS (`occurred_at`) (
