CREATE TABLE `recommendation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `model_version_id` BINARY(16) NOT NULL COMMENT 'Platform model version (soft)',
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `finding` TEXT NOT NULL,
  `evidence` JSON NOT NULL COMMENT 'Top factors (SHAP) and source records',
  `confidence` DECIMAL(7,6) NOT NULL,
  `recommendation` TEXT NOT NULL,
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decision_reason` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci COMMENT 'Required for dismissals',
  `decided_by` BINARY(16),
  `decided_at` DATETIME(6),
  `outcome` JSON COMMENT 'Closed-loop outcome',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recommendation_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_recommendation_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_recommendation__kind` CHECK (`kind` IN ('intervention', 'cover', 'fee_match', 'resource_reallocation', 'curriculum_fix', 'data_fix', 'seating', 'recognition')),
  CONSTRAINT `ck_recommendation__decision` CHECK (`decision` IS NULL OR `decision` IN ('accepted', 'modified', 'dismissed')),
  CONSTRAINT `ck_recommendation__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/transaction/confidential] AI recommendation awaiting a human decision (finding, evidence, confidence, recommendation, decision, outcome)';

CREATE TABLE `risk_flag` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `flag_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `probability` DECIMAL(7,6) NOT NULL COMMENT 'Calibrated',
  `explanation` JSON NOT NULL COMMENT 'Factors; protected characteristics excluded',
  `model_version_id` BINARY(16) NOT NULL,
  `scored_on` DATE NOT NULL,
  `recommendation_id` BINARY(16),
  `dismissed_reason` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_risk_flag_learner_id_flag_kind` (`tenant_id`, `learner_id`, `flag_kind`),
  KEY `ix_risk_flag_recommendation_id` (`tenant_id`, `recommendation_id`),
  CONSTRAINT `ck_risk_flag__flag_kind` CHECK (`flag_kind` IN ('dropout', 'attendance', 'behaviour', 'academic_decline', 'wellbeing', 'send_support_gap')),
  CONSTRAINT `ck_risk_flag__status` CHECK (`status` IN ('new', 'reviewed', 'actioned', 'dismissed', 'expired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/transaction/confidential] Learner early-warning flag (dropout, attendance, behaviour, academic decline, wellbeing, SEND support gap) with explanation';

