  `schema_version` SMALLINT NOT NULL,
  `aggregate_kind` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `aggregate_id` BINARY(16) NOT NULL,
  `scope_node_id_at` BINARY(16),
  `actor` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `correlation_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
