  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`, `created_on`),
  KEY `ix_outbox_event_published_at` (`tenant_id`, `published_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/queue/internal] Transactional outbox of domain events (written with the change; published by CDC; purged 7 days after publication)'
